tool_input.new_string:
// Only the curated, user-facing text (set by createValidationError) crosses
// the boundary — never error.message or a stack trace.
const userMessage = typeof error.userMessage === 'string' ? error.userMessage : undefined;
if (process.send) process.send({ ok: false, code: error.code || 'PARSER_REJECTED', userMessage });

error.code = message?.code || 'PARSER_REJECTED';
// Keep the parser's actionable message ("Could not find a Date column…")
// so the owner can fix the export instead of seeing a generic failure.
if (typeof message?.userMessage === 'string' && message.userMessage.trim()) {
  error.userMessage = message.userMessage.trim().slice(0, 500);
}
finish(error);
